import{_ as o,o as a,c as t,a4 as n}from"./chunks/framework.kn7HWrZO.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"editSource":"docs/glossary.md","rawMarkdownPath":"en/reference/glossary.md"},"headers":[],"relativePath":"en/reference/glossary.md","filePath":"en/reference/glossary.md"}'),r={name:"en/reference/glossary.md"};function s(i,e,l,c,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Domain vocabulary for DeepSeek Harness uses one canonical term per concept. Terms link to their entries with standard Markdown anchors; implementation detail stays in package READMEs and Agent Notes.</p><h2 id="capability-seam" tabindex="-1">capability-seam <a class="header-anchor" href="#capability-seam" aria-label="Permalink to &quot;capability-seam&quot;">​</a></h2><ul><li><strong>seam</strong> — a <em>swappable capability</em> with three roles: a <strong>Service Definition</strong> (the Cordis <code>Service</code> that owns its <code>ctx.&lt;key&gt;</code> and vocabulary types — an abstract class such as <code>ShellExecutor</code>, or a concrete registry such as <code>WebRuntime</code>, never a TypeScript <code>interface</code>), one or more <strong>Service Providers</strong>, and one or more <strong>Consumers</strong> that inject the service. <code>packages/shell</code> is the canonical example: <code>dsh-shell</code> (Service Definition), <code>dsh-bash-local</code> / <code>dsh-bash-sandbox</code> (providers), and <code>dsh-tool-bash</code> (Consumer). Roles normally occupy separate packages when they evolve independently, but a package may own multiple roles when they are one concern (<code>dsh-user-approval</code> owns the approval seam&#39;s Service Definition and its concrete implementation in one package). The seam is the complete capability, never one role; reserve the term for that meaning and name a constituent by its role, class, service, contract, or extension point.</li></ul><h2 id="agent-scope" tabindex="-1">agent-scope <a class="header-anchor" href="#agent-scope" aria-label="Permalink to &quot;agent-scope&quot;">​</a></h2><ul><li><strong>scope</strong> — the unit of per-agent registration: a contribution (tool, prompt section, variable, restriction, listener) is either <em>global</em> (visible to every agent) or <em>scoped</em> (owned by exactly one <a href="#scope-key">scope key</a>). Two levels, flat: scoped registrations do not inherit down to subagents; subtree behavior is expressed with <a href="#lineage">lineage</a> data, never scope structure.</li><li><strong>scope key</strong> — the opaque identity a scope is keyed by, compared by object identity. The harness convention: a live agent is the key of its own scope. <a id="scope-key"></a></li><li><strong>agent context (<code>agent.ctx</code>)</strong> — the agent&#39;s scoped context; registrations through it are scope-visible AND scope-lifetime (one fact drives both), and listeners on it participate in that agent&#39;s scope-filtered dispatches. Registry-subject events may remain deliberately unfiltered under their own event contracts.</li><li><strong>scope carrier</strong> — the <code>thisArg</code> a scope-filtered dispatch carries (built by <code>scopeTarget</code>); its filter admits untagged listeners plus the subject&#39;s own. A <em>subject-less</em> carrier (no key) admits untagged listeners only.</li><li><strong>scoped dispatch</strong> — the rule: an event about one agent&#39;s activity dispatches with that agent&#39;s carrier. Events about a registry itself (a tool was added) are <em>registry-subject</em> and stay unfiltered.</li><li><strong>shadowing</strong> — most-specific-wins name resolution: a scoped tool/section/variable replaces its same-named global twin for that scope alone. The per-agent persona and per-agent tool-variant mechanism.</li><li><strong>restriction / scope-local registration</strong> — a restriction (<code>tools.restrict</code>) filters the GLOBAL tool set for one scope (compose by intersection); scope-local registrations are merged after that filter. A filtered-away global tool is absent from the prompt AND refuses execution, indistinguishably from a nonexistent one.</li><li><strong>setup window</strong> — the creation slot where a creator composes an agent&#39;s scoped world (<code>CreateAgentOptions.setup</code>): after the scope and agent object exist but before the agent or session is published, <code>agent/created</code> fires, or the first prompt is assembled. Setup registers; it never drives the agent.</li><li><strong>lineage</strong> — parent/child facts carried as data (<code>parentSession</code>, durable <code>delegationDepth</code>, runtime <code>subagentDepth</code>); never affects visibility. <a id="lineage"></a></li></ul><h2 id="goal" tabindex="-1">goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;goal&quot;">​</a></h2><ul><li><strong>goal</strong> — one durable completion objective attached to an existing session, with a revisioned <code>active</code> / <code>paused</code> / <code>blocked</code> / <code>complete</code> phase and a goal-round cap; <code>blocked</code> retains a policy code and explanation. A goal is state, not a scheduler or a separate conversation; the session log remains its source of truth.</li><li><strong>goal round</strong> — one continuation cycle admitted for the current goal. The same-session driver materializes a goal round as one goal-sourced <a href="#turn">turn</a>, which can contain zero or more steps; unrelated human turns in the same session do not consume the goal-round cap. <a id="goal-round"></a></li><li><strong>goal activation</strong> — process-local permission for a continuation consumer to admit another goal round. Activation is either <code>armed</code> or <code>disarmed</code>; it is deliberately absent from durable replay, so resume and fork require a later human-authorized resume mutation through <code>/goal</code> or the model tool before automatic work.</li></ul><h2 id="human-command" tabindex="-1">human command <a class="header-anchor" href="#human-command" aria-label="Permalink to &quot;human command&quot;">​</a></h2><ul><li><strong>human command</strong> — a slash-prefixed instruction interpreted and executed by a human-facing adapter through <code>ctx.commands</code>, without becoming a model message. It is distinct from a model-facing tool and from shell command execution through <code>ctx.shell</code>.</li><li><strong>command plane</strong> — discovery, parsing, dispatch, cancellation, and result rendering owned by UI adapters and command plugins. Command output is UI state unless the handler separately mutates a durable domain.</li><li><strong>goal command</strong> — the <code>/goal</code> human command contributed by <code>dsh-command-goal</code>; it observes or mutates the current goal directly while the goal domain owns every durable, model-visible record.</li></ul><h2 id="loop-hierarchy" tabindex="-1">loop hierarchy <a class="header-anchor" href="#loop-hierarchy" aria-label="Permalink to &quot;loop hierarchy&quot;">​</a></h2><ul><li><strong>turn</strong> — one drain of admitted input in a session, ending after the model and its tools stop or a terminal policy intervenes. <a id="turn"></a></li><li><strong>step</strong> — one model request plus the tool executions caused by its response; a turn contains zero or more steps. <a id="step"></a></li><li><strong>round</strong> — an outer policy iteration containing a turn, such as a <a href="#goal-round">goal round</a> or one fresh-agent Ralph attempt. Round counters belong to that policy and do not count every turn in a session. <a id="round"></a></li><li><strong>exchange</strong> — consecutive <a href="#turn">turns</a> from a turn whose first <a href="#step">step</a> admits human input until the next such turn; turns woken by notices, such as settled subagents, goal rounds, or schedules, stay in the preceding exchange. Chat&#39;s next-message folding keeps the latest exchange expanded. <a id="exchange"></a></li></ul><h2 id="ralph" tabindex="-1">Ralph <a class="header-anchor" href="#ralph" aria-label="Permalink to &quot;Ralph&quot;">​</a></h2><ul><li><strong>Ralph loop</strong> — one foreground fresh-agent workflow run toward an immutable objective. It is a model-facing tool policy composed from workflow and subagent primitives, not a same-session goal, agent-loop mode, scheduler, or generic workflow-script feature. <a id="ralph-loop"></a></li><li><strong>Ralph round</strong> — one fresh child session in a <a href="#ralph-loop">Ralph loop</a>. The child receives no parent or prior-child conversation seed; the shared workspace and one bounded <a href="#ralph-handoff">Ralph handoff</a> carry cross-round state. <a id="ralph-round"></a></li><li><strong>Ralph handoff</strong> — the normalized bounded structured report passed from one continuing Ralph round to the next, containing status, summary, evidence, next steps, and blocker text. It supplements the shared workspace rather than replacing it as authority. <a id="ralph-handoff"></a></li></ul>',14)])])}const g=o(r,[["render",s]]);export{u as __pageData,g as default};
